// Generated by scripts/emit-booking.mjs from packages/catalog/booking.json, with refusals from packages/catalog/apis/access.json,
// the badge from packages/catalog/trust.json, the emergency numbers from packages/catalog/sos.json and role
// names from packages/catalog/vetting.json.
// Do not edit by hand — run `npm run booking`. The build fails if this file and its sources disagree,
// so an edit here is lost rather than merely wrong.
//
// Nothing here books anybody. The booking and messaging capabilities are simulated, and every screen that
// reads this says so from the capabilities contract.

import Foundation

enum BookingData {
    static let publishes: [String] = ["booking.requested@1", "booking.confirmed@1", "booking.cancelled@1"]

    enum Person {
        static let stepLabel = "Nurse"
        static let heading = "Who would you like to come?"
        static let lead = "Every nurse offered here is cleared to enter a home today. Ask for one by name, or let the roster send whoever is nearest."
        static let options: [BookingPersonOption] = [
            .init(id: "nearest", name: "Whoever is nearest and cleared", detail: "The nearest nurse whose badge is current takes the visit. You are told who before anybody sets off."),
            .init(id: "previous", name: "The nurse you saw last time", detail: "Offered only while her badge is still current. If it is not, the reason is shown instead of her name."),
            .init(id: "named", name: "A nurse you choose by name", detail: "From the nurses whose badge is current, nearest first.")
        ]
        /// The take-visit gate decides whether a badge is current; the words are trust.json's verified tier.
        static let badgeCapability = "take-visit"
        static let badgeName = "Verified"
        static let badgeSentence = "Identity, credentials and background are all in order today."
        static let worksIn = "Works in {zone}"
        static let namedHeading = "Nurses you can ask for"
        static let notOfferedHeading = "Not offered, and why"
        static let noPrevious = "There is no earlier visit for {person}, so there is nobody to ask for again."
        static let previousNotOffered = "The nurse {person} saw last time is not being offered. {reason}"
        static let asapNeedsNearest = "As soon as someone is free means whoever is nearest. To see one nurse in particular, choose an hour she is offered."
        static let continuity = "Asking for the same nurse is asking, not booking her. An hour she is not offered at is not shown."
    }

    /// What happens to a visit asked of one nurse by name when she cannot take it in Care's offer window.
    enum Fallback {
        /// Access's setting named-nurse-fallback. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let inForce = "patient-chooses"
        static let heading = "If {nurse} cannot take it within {minutes} minutes"
        static let rules: [BookingFallbackRule] = [
            .init(setting: "patient-chooses", offersAsap: true, asksPatient: true, resolvesTo: nil, sentence: "You choose now what happens if {nurse} cannot take this visit within {minutes} minutes of it reaching her."),
            .init(setting: "wait-for-named", offersAsap: false, asksPatient: false, resolvesTo: "wait", sentence: "If {nurse} cannot take this visit within {minutes} minutes of it reaching her, it waits for her and you are told so. Nobody else is sent."),
            .init(setting: "soonest-automatically", offersAsap: true, asksPatient: false, resolvesTo: "soonest", sentence: "If {nurse} cannot take this visit within {minutes} minutes of it reaching her, the soonest nurse whose badge is current takes it, and you are told who before she sets off.")
        ]
        static let choices: [BookingFallbackChoice] = [
            .init(id: "wait", name: "Wait for {nurse}", sentence: "The visit waits for her, and you are told she has not taken it yet. Nobody else is sent."),
            .init(id: "soonest", name: "The soonest nurse who is free", sentence: "The soonest nurse whose badge is current takes it instead, and you are told who before she sets off.")
        ]
        static let reviewLabel = "If she cannot take it"
    }

    enum Time {
        static let fewerHours = "{nurse} is already booked at some of these hours, so they are not shown. Nothing here is a time she was not offered."
        static let noHoursLeft = "{nurse} has no hour left on this day. Choose another day, or ask for whoever is nearest."
    }

    enum Review {
        static let nurseLabel = "Nurse"
        static let nearestValue = "Whoever is nearest and cleared, named before she sets off"
        static let priceLabel = "Price"
        static let cancellingLabel = "Cancelling"
    }

    static let states: [BookingStateWords] = [
        .init(id: "requested", name: "Asked for", patientWords: "You asked for this visit. Nothing is held until a nurse's hour is accepted.", event: "booking.requested@1"),
        .init(id: "confirmed", name: "Accepted", patientWords: "The simulated roster accepted it and holds the hour. No real nurse did.", event: "booking.confirmed@1"),
        .init(id: "cancelled", name: "Cancelled", patientWords: "This visit was called off. It stays here with the reason given.", event: "booking.cancelled@1")
    ]
    static let transitions: [BookingTransition] = [
        .init(from: nil, to: "requested"),
        .init(from: "requested", to: "confirmed"),
        .init(from: "requested", to: "cancelled"),
        .init(from: "confirmed", to: "cancelled")
    ]
    static let statusHeading = "Where this booking stands"
    enum StatusWords {
        static let reached = "Done"
        static let current = "Now"
        static let waiting = "Not yet"
    }
    static let acceptedBy = "Care's engine is not running, so the simulated roster stands in for it. It accepts a chosen hour at once and says that it did, because a preview that waited for nobody would be a screen that never moves."
    static let asapStaysRequested = "Nobody is looking for a nurse, because nothing is running that could. This visit stays asked for, and the screen says so rather than inventing somebody on the way."

    /// booking.json's own refusals, then the routes' refusals it names, each in the route's words.
    static let refusals: [BookingRefusal] = [
        .init(id: "confirm-after-cancel", route: nil, status: nil, sentence: "A cancelled booking is not confirmed afterwards. Book again if the visit is still wanted."),
        .init(id: "confirm-without-a-time", route: nil, status: nil, sentence: "Nothing is accepted until there is an hour to hold."),
        .init(id: "nurse-badge-not-current", route: nil, status: nil, sentence: "A nurse is offered only while her badge is current, so this nurse is not offered."),
        .init(id: "slot-not-offered", route: "POST /v1/access/bookings@1", status: 409, sentence: "That time was not offered, so it cannot be booked."),
        .init(id: "service-not-here", route: "POST /v1/access/bookings@1", status: 422, sentence: "That service is not offered where the visit would be."),
        .init(id: "booking-not-found", route: "GET /v1/access/bookings/{bookingRef}@1", status: 404, sentence: "There is no booking of yours with that reference."),
        .init(id: "cancel-after-arrival", route: "POST /v1/access/bookings/{bookingRef}/cancel@1", status: 409, sentence: "This visit has already started. Speak to the nurse who is with you, or call the Control Tower."),
        .init(id: "reason-not-listed", route: "POST /v1/access/bookings/{bookingRef}/cancel@1", status: 422, sentence: "Choose one of the listed reasons, or say you would rather not."),
        .init(id: "thread-closed", route: "POST /v1/access/visit-threads/{bookingRef}/messages@1", status: 409, sentence: "This visit's thread is closed, so nothing more can be written in it."),
        .init(id: "no-attachments", route: "POST /v1/access/visit-threads/{bookingRef}/messages@1", status: 422, sentence: "A visit thread carries words only. Nothing can be attached."),
        .init(id: "not-on-this-visit", route: "POST /v1/access/visit-threads/{bookingRef}/messages@1", status: 403, sentence: "Only the patient and the nurse on this visit write in its thread."),
        .init(id: "message-too-long", route: "POST /v1/access/visit-threads/{bookingRef}/messages@1", status: 422, sentence: "A message here is kept short. Say the rest to the nurse at the visit."),
        .init(id: "no-summary", route: "POST /v1/access/conversations/{conversationRef}/handover@1", status: 422, sentence: "A handover goes with a structured summary, or it does not go.")
    ]

    enum Thread {
        static let title = "Messages about this visit"
        static let openLabel = "Messages with your nurse"
        static let lead = "Between you and the nurse on this visit, about getting there and getting in."
        static let notARecord = "These messages are not part of your health record. Anything clinical you want a nurse to know, tell her at the visit, where it is written down properly."
        static let nobodyWatches = "Nobody watches this thread for emergencies. If it cannot wait, call 10177, or 112 from a mobile."
        static let inputLabel = "Message to your nurse"
        static let sendLabel = "Send"
        /// Access's setting visit-thread-max-characters. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let maxCharacters = 500
        /// Access's setting visit-thread-open-hours-after-visit. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let openHoursAfterVisit = 24
        /// Access's setting visit-thread-photos, which waits on a doctor's clinical review. A proposal nobody has decided. Not clinically reviewed. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let photos = false
        static let empty = "No messages yet. Anything you write stays with this visit."
        static let kept = "Kept with this visit. Not delivered: nothing reaches her phone."
        static let you = "You"
        static let openAfterVisit = "This visit is finished. Its thread stays open for anything that follows from it until {closes}, and then it closes."
        static let wordsOnly = "Words only. Photos and files cannot be sent in this thread."
        static let photosNotInPreview = "Photos are not in this preview yet."
        static let closedBecause: [BookingThreadClosed] = [
            .init(id: "visit-completed", sentence: "This visit is finished, so its thread is closed. What was said stays here to read."),
            .init(id: "booking-cancelled", sentence: "This visit was cancelled, so its thread is closed. What was said stays here to read.")
        ]
    }

    /// Who answers a Gilbert handover and when. The emergency numbers are sos.json's and are not a setting.
    enum Handover {
        /// Access's setting handover-answered-by, as vetting.json names the roles. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let answeredBy: [String] = ["Registered nurse"]
        /// Access's setting handover-hours, in Johannesburg time. A proposal nobody has decided. A default an admin may change on the web; this app has no admin surface and uses it as written here.
        static let hours: [HandoverWindow] = [
            .init(post: "handover-desk", days: ["mon", "tue", "wed", "thu", "fri", "sat", "sun"], from: "06:00", to: "22:00")
        ]
        static let answeredByLabel = "Who answers"
        static let outOfHours = "Nobody is on the nurse handover desk now."
        static let outOfHoursNumbers = "If this cannot wait, do not wait for a nurse. Call 10177, or 112 from a mobile."
        static let callback = "A nurse on the desk would call you back when it opens, {when}. In this preview nobody will, because nobody is on the other end."
        static let opensToday = "today at {time}"
        static let opensTomorrow = "tomorrow at {time}"
        static let opensOn = "on {day} at {time}"
    }
}
